/**
 * Port -> trading zone (FE, SEAS, ECI, …). Data: public/zones.json, generated by scripts/build_zones.py
 * from the desktop app's WPI list, UN/LOCODE seaports and scripts/zone_rules.json.
 *
 * With a country (ISO code from the extraction), only that country's ports are considered, which settles
 * same-name ports (ODESSA UA vs US). Without one, a name that exists in several zones is UNKNOWN rather
 * than a guess. Matching steps (exact → whole word → ignoring punctuation → close spelling) follow the
 * desktop app's lookup_value(). Users can override any port; overrides live in this browser's localStorage.
 */

type CountryZones = Record<string, string>; // country code -> zone
type ZoneData = {
  zones: string[];
  countries: Record<string, string>;
  aliases: Record<string, string>;
  noise: string;
  curated: Record<string, CountryZones>;
  wpi: Record<string, string | string[]>;
  un: Record<string, CountryZones>;
  country_zones: Record<string, string[]>;
};

type Index = { zones: Map<string, Set<string>>; keys: string[]; collapsed: Map<string, Set<string>> };

export const UNKNOWN = "UNKNOWN";
const OVERRIDES_KEY = "mailai.zoneOverrides";

let data: ZoneData | null = null;
let loading: Promise<ZoneData> | null = null;
let global: Index | null = null;
const byCountry = new Map<string, Index>();
const cache = new Map<string, string>();

export function loadZones(): Promise<ZoneData> {
  loading ??= fetch(new URL("zones.json", new URL(import.meta.env.BASE_URL, location.origin)))
    .then((r) => r.json() as Promise<ZoneData>)
    .then((d) => (initZones(d), d));
  return loading;
}

const collapse = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const only = (set: Set<string> | undefined) => (set?.size === 1 ? [...set][0] : null);

function buildIndex(zones: Map<string, Set<string>>): Index {
  const keys = [...zones.keys()].filter((k) => k.length >= 5);
  const collapsed = new Map<string, Set<string>>();
  for (const k of keys) {
    const c = collapse(k);
    if (c.length < 5) continue;
    const set = collapsed.get(c) ?? new Set<string>();
    zones.get(k)!.forEach((z) => set.add(z));
    collapsed.set(c, set);
  }
  return { zones, keys, collapsed };
}

/** Index zone data (exported separately so tests can supply data without fetch). */
export function initZones(d: ZoneData) {
  data = d;
  cache.clear();
  byCountry.clear();
  // Without a country, the most trusted source that knows a name decides: curated > WPI > UN/LOCODE.
  const zones = new Map<string, Set<string>>();
  for (const [name, cz] of Object.entries(d.un)) zones.set(name, new Set(Object.values(cz)));
  for (const [name, z] of Object.entries(d.wpi)) zones.set(name, new Set(Array.isArray(z) ? z : [z]));
  for (const [name, cz] of Object.entries(d.curated)) zones.set(name, new Set(Object.values(cz)));
  global = buildIndex(zones);
}

function countryIndex(cc: string): Index {
  let idx = byCountry.get(cc);
  if (!idx) {
    const zones = new Map<string, Set<string>>();
    for (const [name, cz] of Object.entries(data!.un)) if (cz[cc]) zones.set(name, new Set([cz[cc]]));
    idx = buildIndex(zones);
    byCountry.set(cc, idx);
  }
  return idx;
}

export const zoneCodes = () => data?.zones ?? [];

export function getOverrides(): Record<string, string> {
  try {
    return JSON.parse(localStorage.getItem(OVERRIDES_KEY) || "{}");
  } catch {
    return {};
  }
}

export function setOverride(port: string, zone: string | null) {
  const o = getOverrides();
  const key = port.trim().toUpperCase();
  if (zone) o[key] = zone;
  else delete o[key];
  localStorage.setItem(OVERRIDES_KEY, JSON.stringify(o));
  cache.clear();
}

function normalizePort(name: string): string {
  const noise = new RegExp(data!.noise, "i");
  let prev: string | null = null;
  let n = name.trim().toUpperCase();
  while (prev !== n) {
    prev = n;
    n = n.replace(noise, "").trim();
  }
  return n;
}

/** Ratcliff/Obershelp similarity, same measure as Python's difflib.SequenceMatcher.ratio(). */
function ratio(a: string, b: string): number {
  const matches = (s1: string, s2: string): number => {
    if (!s1 || !s2) return 0;
    let best = 0, i1 = 0, i2 = 0;
    for (let i = 0; i < s1.length; i++) {
      for (let j = 0; j < s2.length; j++) {
        let k = 0;
        while (i + k < s1.length && j + k < s2.length && s1[i + k] === s2[j + k]) k++;
        if (k > best) { best = k; i1 = i; i2 = j; }
      }
    }
    if (!best) return 0;
    return best + matches(s1.slice(0, i1), s2.slice(0, i2)) + matches(s1.slice(i1 + best), s2.slice(i2 + best));
  };
  return a.length + b.length ? (2 * matches(a, b)) / (a.length + b.length) : 0;
}

/** Zone for a name within an index, or null if not found / ambiguous. */
function match(candidates: string[], idx: Index): string | null {
  // 1. Exact name.
  for (const c of candidates) {
    const z = only(idx.zones.get(c));
    if (z) return z;
    if (idx.zones.get(c)?.size) return null; // known name, but ambiguous: don't guess via fuzzier steps
  }
  // 2. Whole-word containment either way ("PORT OF SANTOS" ~ "SANTOS").
  for (const c of candidates) {
    const found = new Set<string>();
    for (const k of idx.keys) {
      if (new RegExp(`\\b${escapeRe(k)}\\b`).test(c) || new RegExp(`\\b${escapeRe(c)}\\b`).test(k)) {
        idx.zones.get(k)!.forEach((z) => found.add(z));
        if (found.size > 1) break;
      }
    }
    const z = only(found);
    if (z) return z;
  }
  // 3. Ignoring spaces and punctuation ("GO-GIA" ~ "GOGIA").
  for (const c of candidates) {
    const cc = collapse(c);
    if (cc.length < 5) continue;
    const exact = only(idx.collapsed.get(cc));
    if (exact) return exact;
    const found = new Set<string>();
    for (const [ck, zs] of idx.collapsed) {
      if (ck.includes(cc)) zs.forEach((z) => found.add(z));
      if (found.size > 1) break;
    }
    const z = only(found);
    if (z) return z;
  }
  // 4. Close spelling (difflib cutoff 0.88), only when the best match is unambiguous.
  for (const c of candidates) {
    const scored = idx.keys
      .filter((k) => Math.abs(k.length - c.length) <= Math.ceil(c.length * 0.25))
      .map((k) => [k, ratio(c, k)] as const)
      .filter(([, r]) => r >= 0.88)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3);
    if (!scored.length) continue;
    const [best, bestRatio] = scored[0];
    const bestZone = only(idx.zones.get(best));
    if (!bestZone) continue;
    const differing = scored.find(([k]) => only(idx.zones.get(k)) !== bestZone);
    if (!differing || bestRatio - differing[1] >= 0.05) return bestZone;
  }
  return null;
}

/** Zone for an open location (and its ISO country code, when known), or UNKNOWN. Call loadZones() first. */
export function zoneFor(location: string | null, country?: string | null): string {
  if (!location || !data) return UNKNOWN;
  const input = location.trim().toUpperCase();
  const override = typeof localStorage === "undefined" ? undefined : getOverrides()[input];
  if (override) return override;
  const cc = country?.trim().toUpperCase() || "";
  const key = `${input}|${cc}`;
  if (!cache.has(key)) cache.set(key, lookup(input, cc));
  return cache.get(key)!;
}

function lookup(input: string, cc: string): string {
  const d = data!;
  if (d.zones.includes(input)) return input;
  if (d.countries[input]) return d.countries[input];
  if (d.aliases[input]) return d.aliases[input];

  const normalized = normalizePort(input);
  const candidates = input === normalized ? [input] : [input, normalized];

  const possible = d.country_zones[cc];
  if (possible?.length) {
    const inCountry = match(candidates, countryIndex(cc));
    if (inCountry) return inCountry;
    const anywhere = match(candidates, global!);
    if (anywhere && possible.includes(anywhere)) return anywhere;
    return possible.length === 1 ? possible[0] : UNKNOWN; // e.g. any UA port is BSEA
  }
  return match(candidates, global!) ?? UNKNOWN;
}
